from django.db import models
import uuid
import hashlib
import hmac
import json
import base64
from datetime import datetime


class PCAuthentication(models.Model):
    """Stores PC authentication with user code and serial number"""
    id = models.AutoField(primary_key=True)
    
    # User Code - Generated by PC (UUID format)
    user_code = models.CharField(
        max_length=36, 
        unique=True, 
        db_index=True,
        help_text="UUID format: fd342ad9-1c58-47cc-b928-e2061b292cfd"
    )
    
    # Serial Number - Generated by Manufacturer
    serial_number = models.TextField(
        blank=True, 
        null=True,
        help_text="Encrypted serial from manufacturer"
    )
    
    # Authentication Status
    is_authenticated = models.BooleanField(default=False)
    
    # Timestamps
    activated_at = models.DateTimeField(blank=True, null=True)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)
    
    class Meta:
        db_table = 'pc_authentication'
        ordering = ['-created_at']
    
    def __str__(self):
        return f"{self.user_code} - Authenticated: {self.is_authenticated}"
    
    @staticmethod
    def generate_user_code():
        """Generate unique UUID user code"""
        return str(uuid.uuid4())
    
    @staticmethod
    def generate_serial_number(user_code, secret_key):
        """
        Manufacturer generates serial number from user code
        This should be called on manufacturer's side only
        """
        # Create payload
        payload = {
            'user_code': user_code,
            'issued_at': datetime.now().isoformat(),
            'valid': True,
            'version': '1.0'
        }
        
        # Convert to JSON
        json_payload = json.dumps(payload, sort_keys=True)
        
        # Create HMAC signature
        signature = hmac.new(
            secret_key.encode(),
            json_payload.encode(),
            hashlib.sha256
        ).digest()
        
        # Combine and encode
        combined = json_payload.encode() + b'||' + signature
        serial_number = base64.b64encode(combined).decode()
        
        return serial_number
    
    @staticmethod
    def verify_serial_number1(user_code, serial_number, secret_key):
        """
        Verify serial number is valid for this user code
        Returns: (is_valid: bool, message: str)
        """
        try:
            # Decode
            combined = base64.b64decode(serial_number)
            
            # Split
            parts = combined.split(b'||')
            if len(parts) != 2:
                return False, "Invalid serial format"
            
            json_payload, signature = parts
            
            # Verify signature
            expected_signature = hmac.new(
                secret_key.encode(),
                json_payload,
                hashlib.sha256
            ).digest()
            
            if not hmac.compare_digest(signature, expected_signature):
                return False, "Invalid or tampered serial number"
            
            # Parse payload
            payload = json.loads(json_payload.decode())
            
            # Verify user code matches
            if payload.get('user_code') != user_code:
                return False, "Serial number does not match this PC"
            
            if not payload.get('valid'):
                return False, "Serial number revoked"
            
            return True, "Serial verified successfully"
            
        except Exception as e:
            return False, f"Verification failed: {str(e)}"
    
    @staticmethod
    def verify_serial_number(user_code, serial_number, secret_key):
        """Verify serial number is valid for this user code"""
        try:
            # Decode Base64
            combined = base64.b64decode(serial_number)
            
            # Split payload and signature
            parts = combined.split(b'||')
            if len(parts) != 2:
                return False, "Invalid serial format"
            
            json_payload_bytes, signature = parts
            
            # Parse original payload
            payload = json.loads(json_payload_bytes.decode())
            
            # ✅ CRITICAL FIX: Re-create JSON with SAME sorting as generation
            expected_json_payload = json.dumps(payload, sort_keys=True).encode()
            
            # Verify HMAC signature
            expected_signature = hmac.new(
                secret_key.encode(),
                expected_json_payload,  # Use identically sorted JSON
                hashlib.sha256
            ).digest()
            
            if not hmac.compare_digest(signature, expected_signature):
                return False, "Invalid or tampered serial number"
            
            # Verify payload contents
            if payload.get('user_code') != user_code:
                return False, "Serial number does not match this PC"
            if not payload.get('valid'):
                return False, "Serial number revoked"
            
            return True, "Serial verified successfully"
            
        except json.JSONDecodeError:
            return False, "Invalid JSON payload"
        except base64.binascii.Error:
            return False, "Invalid Base64 encoding"
        except Exception as e:
            return False, f"Verification failed: {str(e)}"

   
   
   
    def activate(self, serial_number, secret_key):
        """Activate this PC with serial number"""
        is_valid, message = self.verify_serial_number(
            self.user_code,
            serial_number,
            secret_key
        )
        
        if is_valid:
            self.serial_number = serial_number
            self.is_authenticated = True
            self.activated_at = datetime.now()
            self.save()
            return True, "PC activated successfully"
        else:
            return False, message



