from django.db.models import Q, UniqueConstraint

class Media(models.Model):
    MEDIA_TYPES = [
        ('Optical', 'Optical'),
        ('RS232', 'RS232'),
        ('TCP/IP Client', 'TCP/IP Client'),
        ('TCP/IP Server', 'TCP/IP Server')
    ]
    
    
    device     = models.ForeignKey(Device, on_delete=models.CASCADE,default=1)
    user = models.ForeignKey(member, on_delete=models.CASCADE, default=1)  # assu
    media = models.CharField(max_length=50, choices=MEDIA_TYPES)
    protocol = models.CharField(max_length=50)
    overTimes = models.IntegerField()
    retries = models.IntegerField()
    portName = models.CharField(max_length=50, null=True, blank=True)
    baudRate = models.CharField(max_length=50, null=True, blank=True)
    remoteIP = models.CharField(max_length=50, null=True, blank=True)
    remotePort = models.CharField(max_length=50, null=True, blank=True)
    wakeUpMode = models.BooleanField(null=True, blank=True)
    is_active  = models.BooleanField(default=False, help_text="Only one per device may be active")
    
    class Meta:
        constraints = [
            UniqueConstraint(
                fields=["device"],
                condition=Q(is_active=True),
                name="unique_active_media_per_device"
            )
        ]

    def __str__(self):
        status = " (active)" if self.is_active else ""
        return f"{self.device.serial_number} → {self.media}/{self.protocol}{status}"




