from django.db import models

class PPPSetup(models.Model):
    TYPE_CHOICES = [
        ("LCP", "LCP"),
        ("IPCP", "IPCP"),
    ]
    device = models.ForeignKey('Device', on_delete=models.CASCADE, related_name='ppp_setup') # Foreign key to Device if needed
    phy_reference = models.CharField(max_length=255, blank=True, null=True)
    type = models.CharField(max_length=50, choices=TYPE_CHOICES, help_text="Type of option (LCP or IPCP).")
    lcp_value = models.IntegerField(blank=True, null=True, help_text="Value for the selected LCP option.")
    ipcp_value = models.CharField(max_length=10, blank=True, null=True, choices=[("Enable", "Enable"), ("Disable", "Disable")], help_text="Value for the selected IPCP option (Enable/Disable).")
    LCP_TYPE = models.CharField(max_length=50, blank=True, null=True)
    IPCP_TYPE = models.CharField(max_length=50, blank=True, null=True)
    AUTH_TYPES = [("PAP LOGIN", "PAP LOGIN"), ("CHAP", "CHAP")]
    auth_type = models.CharField(max_length=50, choices=AUTH_TYPES, default="PAP LOGIN", help_text="Authentication type (PAP LOGIN or CHAP).")
    username = models.CharField(max_length=255, blank=True, null=True, help_text="Username for PPP authentication.")
    password = models.CharField(max_length=255, blank=True, null=True, help_text="Password for PPP authentication.")

    def __str__(self): return f"PPP Setup - {self.id}"




from django.db import models

class EnergyRegister(models.Model):
    ENERGY_TYPES = [
        ('active', 'Active Energy'),
        ('reactive', 'Reactive Energy'),
        ('apparent', 'Apparent Energy'),
        ('instantaneous', 'Instantaneous Values'),
        ('average', 'Average Values'),
        ('sliding_average', 'Sliding Average Values'),
    ]

    device = models.ForeignKey('Device', on_delete=models.CASCADE, related_name='energy_register') # Foreign key to Device if needed
    energy_type = models.CharField(max_length=15, choices=ENERGY_TYPES)  # Type of energy
    label = models.CharField(max_length=255)  # Descriptive name of the energy type
    code = models.CharField(max_length=255)  # Unique identifier for the register
    value = models.DecimalField(max_digits=10, decimal_places=2, null=True, blank=True)  # Value of the energy register

    class Meta:
        verbose_name = "Energy Register"
        verbose_name_plural = "Energy Registers"
        unique_together = ('energy_type', 'code')  # Ensures no duplicate energy register codes
        unique_together = ('device', 'code')  # Ensures uniqueness of the combination

    def __str__(self):
        return f'{self.label} ({self.code}) - Value: {self.value}'










