    created_at = models.DateTimeField(auto_now_add=True)  # Automatically sets the date when record is created

    class Meta:
        verbose_name = "Demand Configuration"
        verbose_name_plural = "Demand Configurations"

    def __str__(self):
        return f"{self.name} - {self.code} - Attribute {self.attribute}"

    def get_attribute_display(self):
        return dict(self.SUB_INTERVAL_CHOICES).get(self.attribute, 'Unknown')
    








