    device = models.ForeignKey('Device', on_delete=models.CASCADE, related_name="active_maximum_demand_registers")
    name = models.CharField(max_length=255)
    register_code = models.CharField(max_length=255)  # e.g. "3,1-0:1.8.0.255"
    
    value = models.DecimalField(max_digits=10, decimal_places=2)
    
    

    def __str__(self):
        return f"{self.device} - {self.name} - {self.value} at {self.capture_time}"



