class TokenCredit(models.Model):
    CREDIT_TYPES = [
        ('prepaid', 'Prepaid'),
        ('postpaid', 'Postpaid'),
    ]

    # Value Page Fields
    device = models.ForeignKey(
        Device,
        on_delete=models.CASCADE,
        related_name="token_credit"
    )  # Link to Device model
    current_credit_amount = models.DecimalField(max_digits=10, decimal_places=2, default=0.00)
    credit_type = models.CharField(max_length=10, choices=CREDIT_TYPES, default='prepaid')
    priority = models.IntegerField(default=0)
    limit = models.DecimalField(max_digits=10, decimal_places=2, default=0.00)
    credit_configuration = models.TextField(blank=True, null=True)
    preset_credit_amount = models.DecimalField(max_digits=10, decimal_places=2, default=0.00)
    credit_available_threshold = models.DecimalField(max_digits=10, decimal_places=2, default=0.00)
    period = models.CharField(max_length=50, blank=True, null=True)

    def update_amount(self, amount):
        """Updates the current credit amount."""
        self.current_credit_amount += amount
        self.save()
        return self.current_credit_amount

    def set_amount(self, amount):
        """Sets the credit amount to a specific value."""
        self.current_credit_amount = amount
        self.save()
        return self.current_credit_amount

    def invoke_credit(self, amount):
        """Reduces the credit amount when used, ensuring it doesn't go negative."""
        if self.current_credit_amount >= amount:
            self.current_credit_amount -= amount
            self.save()
            return self.current_credit_amount
        else:
            raise ValueError("Insufficient credit balance")

    def __str__(self):
        return f"TokenCredit (Current: {self.current_credit_amount}, Type: {self.credit_type})"



from decimal import Decimal

class EmergencyCredit(models.Model):
    CREDIT_TYPES = [
        ('emergency', 'Emergency Credit'),
        ('regular', 'Regular Credit'),
    ]
    
    # Fields for Emergency Credit
    device = models.ForeignKey(
        'Device',  # Ensure 'Device' is the correct model
        on_delete=models.CASCADE,
        related_name="emergency_credit"
    )  # Link to Device model
    
    current_credit_amount = models.DecimalField(max_digits=10, decimal_places=2, default=Decimal("0.00"))
    credit_type = models.CharField(max_length=20, choices=CREDIT_TYPES, default='emergency')
    priority = models.IntegerField(default=0)
    
    # New Fields Based on Description
    warning_threshold_1 = models.DecimalField(max_digits=10, decimal_places=2, default=Decimal("0.00"))
    limit = models.DecimalField(max_digits=10, decimal_places=2, default=Decimal("0.00"))
    credit_configuration = models.TextField(blank=True, null=True)
    credit_status = models.CharField(max_length=20, default='active')  # New Field for Credit Status (active/inactive)
    preset_credit_amount = models.DecimalField(max_digits=10, decimal_places=2, default=Decimal("0.00"))
    credit_available_threshold = models.DecimalField(max_digits=10, decimal_places=2, default=Decimal("0.00"))
    period = models.CharField(max_length=50, blank=True, null=True)
    
    # Methods to update/set/invoke credit
    def update_amount(self, amount):
        """Updates the current emergency credit amount."""
        self.current_credit_amount += amount
        self.save()
        return self.current_credit_amount

    def set_amount(self, amount):
        """Sets the emergency credit amount to a specific value."""
        self.current_credit_amount = amount
        self.save()
        return self.current_credit_amount

    def invoke_credit(self, amount):
        """Deducts the emergency credit amount, ensuring it doesn't go negative."""
        if self.current_credit_amount >= amount:
            self.current_credit_amount -= amount
            self.save()
            return self.current_credit_amount
        else:
            raise ValueError("Insufficient emergency credit balance")

    def __str__(self):
        return f"EmergencyCredit (Current: {self.current_credit_amount}, Type: {self.credit_type}, Status: {self.credit_status})"




