# models.py (in meter1 app)
from django.db import models
from django.utils import timezone

LOG_TYPE_CHOICES = [
    ("standard", "StandardEventLog"),
    ("fraud", "FraudDetectionLog"),
    ("disconnector", "DisconnectorControlLog"),
    ("power_quality", "PowerQualityLog"),
    ("communication", "CommunicationLog"),
    ("other", "Other"),
]

class EventLog(models.Model):
    device = models.ForeignKey("meter1.Device", on_delete=models.CASCADE, related_name="event_logs")
    entry_no = models.PositiveIntegerField()
    log_type = models.CharField(max_length=32, choices=LOG_TYPE_CHOICES, default="standard")
    event_time = models.DateTimeField(default=timezone.now)
    event_code = models.CharField(max_length=100)

    class Meta:
        unique_together = ("device", "entry_no", "log_type")
        ordering = ["log_type", "entry_no"]
        indexes = [
            models.Index(fields=["device", "log_type", "entry_no"], name="evtlog_dev_type_entry_idx"),
            models.Index(fields=["device", "event_time"], name="evtlog_dev_time_idx"),
        ]

    def __str__(self):
        return f"{self.device.serial_number} | {self.log_type} | #{self.entry_no} | {self.event_code}"

    def to_dict(self):
        return {
            "no": self.entry_no,
            "log_type": self.log_type,
            "time": self.event_time.isoformat() if self.event_time else None,
            "event_code": self.event_code,
        }



LOG_TYPE_CHOICES2 = [
    
   
    ("purchase", "PurchaseLog"),
    ("long_power_down", "LongPowerDownLog"),
    ("token_transfer", "TokenTransferLog"),
]


class EventLog2(models.Model):
   
    device = models.ForeignKey("meter1.Device", on_delete=models.CASCADE, related_name="event_logs_purchase")
    entry_no = models.PositiveIntegerField()
    log_type = models.CharField(max_length=32, choices=LOG_TYPE_CHOICES2, default="purchase")
    event_time = models.DateTimeField(default=timezone.now)

   
    purchase_token = models.CharField(max_length=128, blank=True, null=True)
   
    purchase_credit = models.DecimalField(max_digits=14, decimal_places=2, null=True, blank=True)

    

    class Meta:
        unique_together = ("device", "entry_no", "log_type")
        ordering = ["log_type", "entry_no"]
        indexes = [
            models.Index(fields=["device", "log_type", "entry_no"], name="evtlog2_dev_type_entry_idx"),
            models.Index(fields=["device", "event_time"], name="evtlog2_dev_time_idx"),
        ]

    def __str__(self):
        return f"{self.device.serial_number} | {self.log_type} | #{self.entry_no}"

    def to_dict(self):
        return {
            "no": self.entry_no,
            "log_type": self.log_type,
            "time": self.event_time.isoformat() if self.event_time else None,
            "purchase_token": self.purchase_token,
            "purchase_credit": (str(self.purchase_credit) if self.purchase_credit is not None else None),
            
        }
    



class ExecuteCommand(models.Model):
    """
    Stores available/known commands per device and the last time they were executed.
    Minimal fields as requested.
    """
    device = models.ForeignKey(
        Device,
        on_delete=models.CASCADE,
        related_name="execute_commands"
    )
    no = models.PositiveIntegerField(db_index=True)
    name = models.CharField(max_length=255)
    code = models.CharField(max_length=255)
    is_active = models.BooleanField(default=True)
    last_executed_at = models.DateTimeField(null=True, blank=True)

    class Meta:
        ordering = ["no"]
        unique_together = (("device", "name", "code"),)  # ensures uniqueness per device

    def __str__(self):
        return f"{self.no}. {self.name} ({self.device})"



class LoadProfileReading(models.Model):
    """
    Single model to hold LoadProfile readings for any period (period 1, 2, ...).
    Fields:
      - device: FK to Device
      - period: which loadprofile period this reading belongs to (1,2,...)
      - entry_no: entry index within that period
      - reading_datetime: timestamp
      - active_import, active_export, reactive_import, reactive_export
    """
    device = models.ForeignKey(Device, on_delete=models.CASCADE, related_name='loadprofile_readings')
    period = models.PositiveSmallIntegerField(default=1, help_text="Load profile period number (1,2,...)")
    entry_no = models.PositiveIntegerField(verbose_name="Entry No")
    reading_datetime = models.DateTimeField(verbose_name="Reading Timestamp")

    # numeric fields for energy values — change max_digits/decimal_places if needed
    active_import = models.DecimalField(max_digits=18, decimal_places=6, null=True, blank=True)
    active_export = models.DecimalField(max_digits=18, decimal_places=6, null=True, blank=True)
    reactive_import = models.DecimalField(max_digits=18, decimal_places=6, null=True, blank=True)
    reactive_export = models.DecimalField(max_digits=18, decimal_places=6, null=True, blank=True)

    class Meta:
        ordering = ['period', 'entry_no']
        # unique per device + period + entry_no (prevents duplicate entries for same period)
        unique_together = ('device', 'period', 'entry_no')
        verbose_name = "LoadProfile Reading"
        verbose_name_plural = "LoadProfile Readings"

    def __str__(self):
        return f"{self.device.serial_number} - period {self.period} - entry {self.entry_no}"




class PowerQualityReading(models.Model):
    """
    A single power-quality reading / table row.
    Fields map to your dashboard columns:
      - entry_no (No)
      - reading_datetime (Clock)
      - disconnect_control_state (Disconnect control state)
      - instantaneous_voltage_l1 (Instantaneous voltage L1)
      - instantaneous_current_l1 (Instantaneous current L1)
    """
    device = models.ForeignKey(Device, on_delete=models.CASCADE, related_name='power_quality_readings')
    entry_no = models.PositiveIntegerField(verbose_name="Entry No")
    reading_datetime = models.DateTimeField(verbose_name="Reading Timestamp")

    # state / descriptive field
    disconnect_control_state = models.CharField(max_length=128, blank=True, null=True,
                                                help_text="E.g. '(1) Connected' or state code")

    # numeric measurement fields (adjust precision if needed)
    instantaneous_voltage_l1 = models.DecimalField(max_digits=10, decimal_places=3, null=True, blank=True,
                                                   help_text="Voltage in V")
    instantaneous_current_l1 = models.DecimalField(max_digits=10, decimal_places=3, null=True, blank=True,
                                                   help_text="Current in A")

    class Meta:
        ordering = ['entry_no']
        unique_together = ('device', 'entry_no')  # prevent duplicate entry numbers per device
        indexes = [
            models.Index(fields=['device', 'entry_no']),
            models.Index(fields=['device', 'reading_datetime']),
        ]
        verbose_name = "Power Quality Reading"
        verbose_name_plural = "Power Quality Readings"

    def __str__(self):
        return f"{self.device.serial_number} - entry {self.entry_no} - {self.reading_datetime.isoformat()}"




